perl -e '
use strict;
use warnings;
use File::Find;

my @decls;
my $decl_re = qr/^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/;

find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $path = $File::Find::name;
  return unless $path =~ m{/internal/};
  open my $fh, "<", $path or die $!;
  my $pkg = "";
  my $n = 0;
  while (my $line = <$fh>) {
    $n++;
    $pkg = $1 if $line =~ /^package\s+(\w+)/;
    if ($line =~ $decl_re) {
      push @decls, {pkg=>$pkg, recv=>$1//"", name=>$2, path=>$path, line=>$n};
    }
  }
}, "/bench/repo/internal");

print "count=".scalar(@decls)."\n";
for my $d (@decls) {
  print "$d->{pkg}.$d->{name} recv=$d->{recv} $d->{path}:$d->{line}\n";
}
'

find /bench/repo/internal -name "*.go" ! -name "*_test.go" -print0 | perl -0 -ne '
use strict;
